head.script:
//
(function () {
  try {
    var path = window.location.pathname;
    if (!path || path.indexOf('/p/') !== 0) { return; }
    var raw = null;
    try { raw = window.localStorage.getItem('ezy_plugin_menu_cache'); } catch (e) { return; }
    if (!raw) { return; }
    var cached = null;
    try { cached = JSON.parse(raw); } catch (e) { return; }
    if (!cached || !cached.data) { return; }
    var groups = cached.data;
    var files = [];
    for (var g = 0; g < groups.length; g++) {
      var items = (groups[g] && groups[g].items) || [];
      for (var k = 0; k < items.length; k++) {
        var p = items[k];
        if (!p) { continue; }
        var link = p.link || ('/p/' + (p.pageSlug || p.page || p.pluginId || p.id || '') + '.html');
        var pageIdAlt = (p.pageId && String(p.pageId).charAt(0) === '/') ? p.pageId : '';
        if (link !== path && pageIdAlt !== path) { continue; }
        var az = p.assets;
        if (az && typeof az === 'object') {
          if (az.css) { files = files.concat(az.css); }
          if (az.js) { files = files.concat(az.js); }
        }
        if (p.scripts && p.scripts.length) { files = files.concat(p.scripts); }
      }
    }
    var seen = {};
    var base = String(window.PLUGIN_ASSET_BASE || '').replace(/\/+$/, '');
    for (var f = 0; f < files.length; f++) {
      var file = String(files[f] || '').replace(/^\/+/, '');
      if (!file || seen[file]) { continue; }
      seen[file] = true;
      var url = (file.indexOf('://') !== -1 || file.charAt(0) === '/') ? file : (base + '/' + file);
      try {
        if (file.slice(-4).toLowerCase() === '.css') {
          var lk = document.createElement('link');
          lk.rel = 'stylesheet';
          lk.href = url;
          document.head.appendChild(lk);
        } else {
          var s = document.createElement('script');
          s.async = false;
          s.src = url;
          document.head.appendChild(s);
        }
      } catch (e) {}
    }
  } catch (e) {}
})();
//

//
(function () {
  'use strict';

  window.EzyFast = window.EzyFast || {};

  var CONFIG = null;
  function getConfig() {
    if (CONFIG) { return CONFIG; }
    try {
      var el = document.getElementById('ezyfast-core-config');
      CONFIG = JSON.parse((el && el.textContent) || '{}');
    } catch (err) {
      // JSON gagal di-parse (mis. tag <data:view.postId/> tidak ter-render
      // di halaman statis /p/*.html) �+' ekstrak field penting secara manual
      // agar endpoint & blogId tetap tersedia untuk plugin page.
      CONFIG = {};
      try {
        var raw = (document.getElementById('ezyfast-core-config') || { textContent: '' }).textContent || '';
        var m = raw.match(/"gasApiEndpoint"\s*:\s*"([^"]*)"/);
        if (m) { CONFIG.gasApiEndpoint = m[1]; }
        m = raw.match(/"blogId"\s*:\s*"([^"]*)"/);
        if (m) { CONFIG.blogId = m[1]; }
        m = raw.match(/"pageId"\s*:\s*"([^"]*)"/);
        if (m) { CONFIG.pageId = m[1]; }
      } catch (e2) {}
    }
    if (CONFIG && typeof CONFIG.gasApiEndpoint === 'string') {
      var ph = /YOUR_WEB_APP_ID|YOUR_SCRIPT_ID|PASTE_/i;
      if (ph.test(CONFIG.gasApiEndpoint)) { CONFIG.gasApiEndpoint = ''; }
    }
    // pageId: tag data tidak tersedia di semua view �+' turunkan dari URL
    // klien (pathname), mis. /p/calendar.html.
    if (CONFIG && (!CONFIG.pageId || /data:view|<[a-z]+>/i.test(String(CONFIG.pageId)))) {
      CONFIG.pageId = window.location.pathname.replace(/\/+$/, '') || '';
    }
    return CONFIG;
  }

  var AUTH_KEY = 'ezy_auth_token';
  var USER_KEY = 'ezy_auth_user';

  /* == Event Bus: komunikasi antar komponen modular == */
  function toast(message, type) {
    window.dispatchEvent(new CustomEvent('ezy:toast', { detail: { message: message, type: type || 'success' } }));
  }
  function openModal(modalId, payload) {
    window.dispatchEvent(new CustomEvent('ezy:modal:open', { detail: { modalId: modalId, payload: payload || null } }));
  }
  function pluginInstalled(pluginId) {
    window.dispatchEvent(new CustomEvent('ezy:plugin:installed', { detail: { pluginId: pluginId } }));
  }

  window.EzyFast.toast = toast;
  window.EzyFast.openModal = openModal;
  window.EzyFast.pluginInstalled = pluginInstalled;
  window.EzyFast.getConfig = getConfig;
  window.EzyFast.AUTH_KEY = AUTH_KEY;

  /* == Plugin Assets: loader generik pola ${url} (ala EzyCoreAdmin) ===
     window.EzyFast.loadScript(file) / loadCss(file):
     - url penuh (http...) dipakai apa adanya (seperti `isFullUrl`);
     - nama file relatif di-resolve ke PLUGIN_ASSET_BASE (satu SHA).
     - Promise + timeout 15 dtk + dedup (tak ganda walau dipanggil
       dari preloader, injector menu, DAN tag halaman).
     - BEDA dari EzyCoreAdmin: tanpa ?v=timestamp (versi sudah di PATH
       via @SHA �?" tetap cacheable, tetap segar tiap ganti SHA). */
  var __ezyAssetsLoaded = {};

  function pluginAssetUrl(file) {
    if (!file) { return ''; }
    if (file.indexOf('://') !== -1 || file.charAt(0) === '/') { return file; }
    var base = String(window.PLUGIN_ASSET_BASE || '').replace(/\/+$/, '');
    return base + '/' + String(file).replace(/^\/+/, '');
  }

  function pluginAssetPresent(file) {
    try {
      var f = String(file || '') || '';
      var probe = '/' + f.replace(/^\/+/, '');
      // URL absolut (http..) cocok via substring penuh; relatif via probe.
      var isAbs = f.indexOf('://') !== -1;
      var matchVal = function (val) {
        if (!val) { return false; }
        return isAbs ? (val.indexOf(f) !== -1) : (val.indexOf(probe) !== -1);
      };
      var scripts = document.getElementsByTagName('script');
      for (var i = 0; i < scripts.length; i++) {
        if (matchVal(scripts[i].getAttribute('src'))) { return true; }
      }
      var links = document.getElementsByTagName('link');
      for (var j = 0; j < links.length; j++) {
        if (matchVal(links[j].getAttribute('href'))) { return true; }
      }
    } catch (e) {}
    return false;
  }

  // API publik ala EzyCoreAdmin.loadScript: Promise + timeout + dedup.
  // Tandai URL synchronous agar pemanggilan ganda sebelum load selesai
  // tetap satu request; flag dihapus bila gagal agar bisa retry.
  function loadEzyAsset(file, kind) {
    var url = pluginAssetUrl(file);
    if (!url) { return Promise.reject(new Error('EzyFast asset: empty file')); }
    if (__ezyAssetsLoaded[url] || pluginAssetPresent(file)) {
      return Promise.resolve();
    }
    __ezyAssetsLoaded[url] = true;
    return new Promise(function (resolve, reject) {
      var done = false;
      var timer = setTimeout(function () {
        if (!done) { done = true; delete __ezyAssetsLoaded[url]; reject(new Error('EzyFast asset timeout: ' + url)); }
      }, 15000);
      var el;
      if (kind === 'css') {
        el = document.createElement('link');
        el.rel = 'stylesheet';
        el.href = url;
      } else {
        el = document.createElement('script');
        el.async = false;
        el.src = url;
      }
      el.onload = function () {
        if (done) { return; }
        done = true; clearTimeout(timer); resolve();
      };
      el.onerror = function () {
        if (done) { return; }
        done = true; clearTimeout(timer); delete __ezyAssetsLoaded[url]; reject(new Error('EzyFast asset failed: ' + url));
      };
      try { document.head.appendChild(el); }
      catch (e) {
        if (!done) { done = true; clearTimeout(timer); delete __ezyAssetsLoaded[url]; reject(e); }
      }
    });
  }

  window.EzyFast.loadScript = function (file) { return loadEzyAsset(file, 'js'); };
  window.EzyFast.loadCss = function (file) { return loadEzyAsset(file, 'css'); };

  function pluginPageUrl(p) {
    // pageId = path kanonik terdaftar di Plugins_Active (di-sync tiap
    // kunjungan lewat set_plugin_meta). Lebih otoritatif daripada link
    // ber-slug pageSlug yang bisa basi saat halaman dipindahkan/direname.
    if (p.pageId && String(p.pageId).charAt(0) === '/') { return p.pageId; }
    if (p.link) { return p.link; }
    var slug = p.pageSlug || p.page || p.pluginId || p.id || '';
    return '/p/' + slug + '.html';
  }

  // Muat aset plugin milik halaman aktif dari daftar menu.
  // Return Promise.all aset yang diminta (selalu resolve, gagal = ignor).
  // Pemanggil lama (loadPlugins) mengabaikan return �+' tetap kompatibel;
  // SPA Router memakainya untuk menunggu aset plugin sebelum inject konten
  // agar inline script halaman tidak lebih dulu jalan dari JS plugin.
  // Registry plugin �?" TANPA fallback. Sumber kekuatan HANYA backend
  // (SchemaRegistry �+' getAllPlugins �+' get_admin_menu): registry di bawah
  // dikosongkan dan diisi ulang SETIAP kali primePluginRegistry() jalan.
  // Field children/assets/pageId TIDAK pernah didefinisikan ulang di
  // frontend (SchemaRegistry adalah definisi tunggal).
  // Catatan: seed statis pos + fallback aset/slug yang dahulu ada DIHAPUS �?"
  // halaman plugin dikenali begitu data menu backend tiba (aset juga);
  // pos.js tetap termuat karena get_admin_menu selalu membawa assets
  // `{ js: ['pos.js'] }` dari schema.
  var PLUGIN_REGISTRY = {};
  window.EzyFast.PLUGIN_REGISTRY = PLUGIN_REGISTRY;

  // Indeks path �+' key plugin, dibangun HANYA dari pageId/link/page yang
  // datang di get_admin_menu. Dipakai pageKindFor / assetGate agar halaman
  // plugin dikenali dari PATH AKTIF (berapa pun slug-nya) �?" sebuah
  // rename/move halaman cukup di-sync sekali lewat pageId di menu.
  var PLUGIN_PATH_INDEX = {};
  window.EzyFast.PLUGIN_PATH_INDEX = PLUGIN_PATH_INDEX;

  // Resolve key plugin untuk sebuah path. DAPAT TEPAT lewat indeks yang
  // dipopulasi data backend; TANPA tebak slug/nama. '' bila belum dikenal
  // (data menu belum tiba �?" atau memang bukan halaman plugin).
  function pluginKeyForPath(path) {
    path = String(path || '');
    if (!path || path.slice(0, 3) !== '/p/' || path.slice(-5) !== '.html') { return ''; }
    try {
      if (PLUGIN_PATH_INDEX[path]) { return PLUGIN_PATH_INDEX[path]; }
    } catch (e) {}
    return '';
  }
  window.EzyFast.pluginKeyForPath = pluginKeyForPath;

  // == Registry route override (deep-link plugin di luar /p/) ===========
  // Plugin dapat mendaftarkan matcher path → kind baru (mis. permalink post
  // tab POS /yyyy/mm/<slug>.html) serta route-handler yang mengendalikan
  // render()-nya sendiri. API idempoten; matcher dibaca pageKindFor, handler
  // dipanggil render() alih-alih alur default (guard/aset/inject).
  window.EzyFast.__EzyRegRoutes = window.EzyFast.__EzyRegRoutes || [];
  window.EzyFast.__EzyRegHandlers = window.EzyFast.__EzyRegHandlers || {};
  window.EzyFast.registerRoute = function (route) {
    try {
      if (!route || !route.kind || typeof route.match !== 'function') { return; }
      window.EzyFast.__EzyRegRoutes = window.EzyFast.__EzyRegRoutes || [];
      window.EzyFast.__EzyRegRoutes.push(route);
    } catch (e) {}
  };
  window.EzyFast.registerRouteHandler = function (kind, handler) {
    try {
      if (!kind || typeof handler !== 'function') { return; }
      window.EzyFast.__EzyRegHandlers = window.EzyFast.__EzyRegHandlers || {};
      window.EzyFast.__EzyRegHandlers[kind] = handler;
    } catch (e) {}
  };
  window.EzyFast.getRouteHandler = function (kind) {
    try {
      if (kind && window.EzyFast.__EzyRegHandlers) { return window.EzyFast.__EzyRegHandlers[kind] || null; }
    } catch (e) {}
    return null;
  };

  /* == Route statis POS tab (deep-link /yyyy/mm/<slug>.html) ===========
     Permalink tab modul POS dikenali router walau data menu plugin belum
     tiba. Matcher ini statis (4 slug tab POS, lihat AGENTS.md-registerRoute
     & p/plugins/POS/REFACTOR_PLAN.md Fase 2) — engine feed pos.js menimpa
     handler-nya sendiri ketika tersaji (registerRouteHandler 'pos-tab'). */
  (function () {
    var POS_KS = 'pos-tab';
    function posTabSlug(path) {
      var m = String(path || '').match(/^\/(\d{4})\/(\d{2})\/(sale|catalog|transactions|shifts)\.html$/);
      return m ? m[3] : '';
    }
    function fallbackHandler(path) {
      function fallbackInject() {
        try {
          if (window.__EzySpa && typeof window.__EzySpa.loadAdminContent === 'function') {
            window.__EzySpa.loadAdminContent(path);
          }
        } catch (e) {}
      }
      // Sudah ditimpa pos.js → serahkan padanya.
      var cur = window.EzyFast.getRouteHandler(POS_KS);
      if (cur && cur !== fallbackHandler) {
        try { cur(path); } catch (e) { fallbackInject(); }
        return;
      }
      // pos.js belum tersaji: muat aset lalu beri kesempatan handler barunya.
      try {
        var p = window.EzyFast.loadScript('pos.js');
        if (p && typeof p.then === 'function') {
          p.then(function () {
            var cur2 = window.EzyFast.getRouteHandler(POS_KS);
            if (cur2 && cur2 !== fallbackHandler) { try { cur2(path); } catch (e) {} }
            else { fallbackInject(); }
          }).catch(function () { fallbackInject(); });
        } else {
          fallbackInject();
        }
      } catch (e) { fallbackInject(); }
      // Render konten post standar sementara aset datang (tidak blank).
      fallbackInject();
    }
    window.EzyFast.registerRoute({
      kind: POS_KS,
      match: function (path) { return posTabSlug(path) ? true : false; }
    });
    window.EzyFast.registerRouteHandler(POS_KS, fallbackHandler);
    // Loader full-page-load permalink: muat pos.js supaya takeover shell
    // terjadi. Idempoten (loadScript dedup by URL).
    function ensure() {
      try {
        if (!posTabSlug(window.location.pathname)) { return; }
        if (document.getElementById('pos-page')) { return; }
        if (window.__posJsRan) { return; }
        window.EzyFast.loadScript('pos.js');
      } catch (e) {}
    }
    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', ensure);
    } else {
      ensure();
    }
  })();

  // Hydrasi registry dari menu backend (get_admin_menu). Backend sudah
  // men-enrich children (schema library) & assets (getPluginAssets) per
  // item menu, jadi merge di sini cukup menyalin apa adanya �?" frontend
  // TIDAK pernah mendefinisikan ulang schema plugin.
  function primePluginRegistry(menuGroups) {
    try {
      if (!menuGroups || !menuGroups.length) { return; }
      for (var g = 0; g < menuGroups.length; g++) {
        var items = menuGroups[g].items || [];
        for (var i = 0; i < items.length; i++) {
          var p = items[i];
          if (!p) { continue; }
          var slugKey = String(p.pageSlug || p.page || p.pluginId || p.id || '');
          var slugFromLink = '';
          try {
            var m = String(p.link || '').match(/\/p\/([^\/#?]+)\.html/);
            if (m) { slugFromLink = m[1]; }
          } catch (e) {}
          var key = slugKey || slugFromLink;
          if (!key) { continue; }
          var merged = {
            page: p.pagePath || p.link || '/p/' + key + '.html',
            pageId: (typeof p.pageId === 'string') ? p.pageId : '',
            title: p.pageTitle || p.label || p.menuLabel || key,
            assets: (p.assets && typeof p.assets === 'object')
              ? { css: (p.assets.css || []).slice(), js: (p.assets.js || []).slice() }
              : null,
            children: (p.children && p.children.length) ? p.children.slice() : null
          };
          PLUGIN_REGISTRY[key] = Object.assign({}, PLUGIN_REGISTRY[key] || {}, merged);
          // Indeks path�+'key; pageId (path terdaftar di DB) urutan pertama.
          if (merged.pageId && merged.pageId.indexOf('/p/') === 0) { PLUGIN_PATH_INDEX[merged.pageId] = key; }
          if (merged.page && merged.page.indexOf('/p/') === 0) { PLUGIN_PATH_INDEX[merged.page] = key; }
          if (p.link && p.link.indexOf('/p/') === 0) { PLUGIN_PATH_INDEX[p.link] = key; }
        }
      }
    } catch (e) {}
  }
  window.EzyFast.primePluginRegistry = primePluginRegistry;

  function loadPluginAssetsForPage(menuGroups) {
    var all = [];
    try {
      // Hidrasi registry dinamis dari menu backend sebelum dipakai �?"
      // jadikan data backend (SchemaRegistry) satu-satunya sumber field
      // plugin (children, assets, title) di sisi frontend.
      try { if (window.EzyFast && window.EzyFast.primePluginRegistry) { window.EzyFast.primePluginRegistry(menuGroups); } } catch (eP) {}
      if (!menuGroups || !menuGroups.length) { return Promise.resolve(all); }
      var path = window.location.pathname;
      // Kunci plugin untuk PATH AKTIF (via indeks pageId/link) �?" item menu
      // dengan slug basi tetap bisa dicocokkan dengan benar.
      var targetKey = '';
      try { targetKey = pluginKeyForPath(path); } catch (e) {}
      for (var g = 0; g < menuGroups.length; g++) {
        var items = menuGroups[g].items || [];
        for (var k = 0; k < items.length; k++) {
          var p = items[k];
          if (!p) { continue; }
          // Cocokkan pathname; toleransi link absolut vs relatif.
          var pageUrl = pluginPageUrl(p);
          var itemKey = '';
          try { itemKey = String(p.pluginId || p.pageSlug || p.page || p.id || ''); } catch (e) {}
          if (pageUrl !== path && pageUrl.slice(-path.length) !== path &&
              !(targetKey && itemKey === targetKey)) { continue; }
          var cssFiles = [];
          var jsFiles = [];
          if (p.assets && typeof p.assets === 'object') {
            cssFiles = cssFiles.concat(p.assets.css || []);
            jsFiles = jsFiles.concat(p.assets.js || []);
          }
          // Kompatibel legacy: item.scripts[] dianggap file JS.
          if (p.scripts && p.scripts.length) {
            jsFiles = jsFiles.concat(p.scripts);
          }
          var i;
          var requested = [];
          for (i = 0; i < cssFiles.length; i++) {
            requested.push(cssFiles[i]);
            all.push(loadEzyAsset(cssFiles[i], 'css').catch(function () {}));
          }
          for (i = 0; i < jsFiles.length; i++) {
            requested.push(jsFiles[i]);
            all.push(loadEzyAsset(jsFiles[i], 'js').catch(function () {}));
          }
          return Promise.all(all); // satu halaman hanya milik satu plugin
        }
      }
    } catch (e) {}
    return Promise.all(all);
  }

  // Ekspor untuk SPA Router: preloader header HANYA berjalan saat full page
  // load. Navigasi SPA (Pjax) tanpa reload harus meng-inject aset plugin
  // halaman tujuan sendiri memakai pathname baru (setelah pushState).
  window.EzyFast.loadPluginAssetsForPage = loadPluginAssetsForPage;
  // Penanda mode SPA agar plugin (mis. pos.js) tahu router inject berjalan:
  // watchdog plugin TIDAK boleh rehydrate/manipulasi pohon saat SPA sedang
  // inject (lihat isInjecting + rehydratePluginTree di script router).
  window.EzyFast.IS_SPA = true;
  // NOTE: window.EzyFast.rehydratePluginTree di-assign dari SCRIPT ROUTER
  // (IIFE loadAdminContent/injectContent) setelah fungsi rehydratePluginTree
  // didefinisikan �?" referensi silang dengan ini akan ReferenceError karena
  // berada di IIFE berbeda. Lihat blok router.

  /* == Global Overlay Loader (EzyFast.loader) ======================
     SATU loader overlay untuk SEMUA halaman modul, dipakai seragam via:
       window.EzyFast.loader.show('Muat kalender...');
       window.EzyFast.loader.hide();
     Elemen statis #ezy-global-loader didefinisikan di kontainer SPA
     (anchor #ezy-admin-anchor, membungkus #ezy-admin-content). Bila elemen
     tidak ditemukan (mode MPA / halaman standalone), overlay dibuat dinamis
     dengan struktur & gaya identik sehingga tampilan selalu seragam.

     Ref-count: navigasi router & inisialisasi halaman boleh bertumpuk
     tanpa saling membatalkan �?" ini mencegah kasus "loader kepotong" ketika
     init halaman (show sinkron saat reExecuteDynamicContent) terjadi
     sebelum router menutup loadernya (hide). */
  var _ezyLoaderCount = 0;
  var _ezyLoaderEl = null;
  function ezyEnsureLoader() {
    var el = document.getElementById('ezy-global-loader');
    if (el && el.isConnected) { _ezyLoaderEl = el; return el; }
    if (_ezyLoaderEl && _ezyLoaderEl.isConnected) { return _ezyLoaderEl; }
    el = document.createElement('div');
    el.id = 'ezy-global-loader';
    el.innerHTML =
      '<span class="ezy-card-spinner"></span>' +
      '<span class="ezy-loader-text"></span>';
    if (!document.getElementById('ezy-global-loader-style')) {
      var st = document.createElement('style');
      st.id = 'ezy-global-loader-style';
      st.textContent =
        '#ezy-global-loader{position:absolute;inset:0;z-index:30;display:flex;align-items:center;justify-content:center;gap:8px;min-height:240px;background:rgba(255,255,255,0.72);backdrop-filter:blur(2px);-webkit-backdrop-filter:blur(2px)}' +
        ':is(.dark) #ezy-global-loader{background:rgba(17,24,39,0.6)}' +
        '#ezy-global-loader.is-hidden{display:none}' +
        '#ezy-global-loader .ezy-card-spinner{width:22px;height:22px;border-radius:50%;border:3px solid #e5e7eb;border-top-color:var(--brand-primary,#465fff);animation:ezy-spin 0.7s linear infinite;flex-shrink:0}' +
        ':is(.dark) #ezy-global-loader .ezy-card-spinner{border-color:#1f2937}' +
        '#ezy-global-loader .ezy-loader-text{font-size:13px;color:#4b5563}' +
        ':is(.dark) #ezy-global-loader .ezy-loader-text{color:#9ca3af}' +
        '@keyframes ezy-spin{to{transform:rotate(360deg)}}';
      (document.head || document.documentElement).appendChild(st);
    }
    _ezyLoaderEl = el;
    return el;
  }
  function ezyPlaceLoader(el) {
    var host = document.getElementById('ezy-admin-anchor');
    try {
      if (host && host.isConnected) {
        // Mount-once: hanya reparent bila belum berada di host. Jangan
        // remove()+appendChild setiap navigasi �?" mutasi childList berulang
        // tepat di window swap konten adalah pemicu flush MutationObserver
        // Alpine di atas pohon lama �+' badai 'Cannot convert undefined or
        // null to object'.
        if (!el.isConnected || el.parentNode !== host) {
          if (el.parentNode) { try { el.remove(); } catch (e) {} }
          host.appendChild(el);
        }
        el.style.position = '';
        el.style.zIndex = '';
        return;
      }
    } catch (e) {}
    el.style.position = 'fixed';
    el.style.zIndex = '99999';
    // Fallback body: reparent HANYA bila belum terpasang (bukan tiap show).
    if (!el.isConnected || el.parentNode !== document.body) {
      try { if (el.parentNode) { el.parentNode.removeChild(el); } } catch (e) {}
      (document.body || document.documentElement).appendChild(el);
    }
  }
  function ezyLoaderShow(msg) {
    try {
      var el = ezyEnsureLoader();
      ezyPlaceLoader(el);
      var t = el.querySelector('.ezy-loader-text');
      if (t) { t.textContent = msg == null ? 'Memuat...' : String(msg); }
      el.classList.remove('is-hidden');
      _ezyLoaderCount += 1;
    } catch (e) {}
  }
  function ezyLoaderHide() {
    try {
      if (_ezyLoaderCount > 0) { _ezyLoaderCount -= 1; }
      if (_ezyLoaderCount > 0) { return; }
      var el = ezyEnsureLoader();
      el.classList.add('is-hidden');
    } catch (e) {}
  }
  window.EzyFast.loader = { show: ezyLoaderShow, hide: ezyLoaderHide };

  /* == Plugin Menu Cache: stale-while-revalidate ======================
     Cache plugin menu di localStorage agar sidebar tampil instan saat
     reload, tanpa menunggu JSONP round-trip ke GAS backend.           */
  var PLUGIN_CACHE_KEY = 'ezy_plugin_menu_cache';
  var PLUGIN_CACHE_TTL = 5 * 60 * 1000; // 5 menit

  function getCachedPlugins() {
    try {
      var raw = localStorage.getItem(PLUGIN_CACHE_KEY);
      if (!raw) { return null; }
      var cached = JSON.parse(raw);
      if (!cached || !cached.ts || !cached.data) { return null; }
      if (Date.now() - cached.ts > PLUGIN_CACHE_TTL) { return null; }
      return cached.data;
    } catch (e) { return null; }
  }

  function setCachedPlugins(list) {
    try {
      localStorage.setItem(PLUGIN_CACHE_KEY, JSON.stringify({ ts: Date.now(), data: list }));
    } catch (e) {}
  }

  /* == Router: map pathname -> role halaman == */
  function pageKind() {
    var p = window.location.pathname;
    if (p === '/' || p === '/p/home.html' || p === '/p/home.html/') { return 'home'; }
    if (p.indexOf('/search') === 0) { return 'search'; }
    if (p.indexOf('/p/signin.html') === 0) { return 'signin'; }
    if (p.indexOf('/p/signup.html') === 0) { return 'signup'; }
    if (p.indexOf('/p/reset-password.html') === 0) { return 'reset-password'; }
    if (p.indexOf('/p/dashboard-admin.html') === 0) { return 'dashboard-admin'; }
    if (p.indexOf('/p/dashboard-user.html') === 0) { return 'dashboard-user'; }
    if (p.indexOf('/p/profile.html') === 0) { return 'profile'; }
    if (p.indexOf('/p/ai-assistant.html') === 0) { return 'ai-assistant'; }
    if (p.indexOf('/p/plugin-manager.html') === 0) { return 'plugin-manager'; }
    if (p.indexOf('/p/notifikasi.html') === 0) { return 'notifikasi'; }
    return 'page';
  }

  var PAGE_ROLES = {
    home: 'public',
    search: 'public',
    signin: 'guest',
    signup: 'guest',
    'reset-password': 'guest',
    'dashboard-admin': 'admin',
    'dashboard-user': 'protected',
    'plugin-manager': 'admin',
    profile: 'protected',
    'ai-assistant': 'protected',
    notifikasi: 'protected',
    page: 'protected'
  };

  function parseUser(raw) {
    if (!raw) { return null; }
    try { return JSON.parse(raw); } catch (err) { return null; }
  }

  /* == Core Menu Fallback: menu statis yang selalu tampil instan == */
  var DEFAULT_ADMIN_MENU = [
    {
      title: 'MENU ADMIN',
      items: [
        { label: 'Dashboard', icon: 'layout-grid', link: '/p/dashboard-admin.html', page: 'dashboard-admin', roles: ['admin'], scripts: [] },
        { label: 'Plugin Manager', icon: 'blocks', link: '/p/plugin-manager.html', page: 'plugin-manager', roles: ['admin'], scripts: [] },
        { label: 'Ai Assistant', icon: 'bot', link: '/p/ai-assistant.html', page: 'ai-assistant', roles: ['admin'], scripts: [] }
      ]
    },
    {
      title: 'PLUGINS',
      items: []
    }
  ];

  var DEFAULT_CUSTOMER_MENU = [
    {
      title: 'MENU CUSTOMER',
      items: [
        {
          label: 'Dashboard', icon: 'layout-grid', link: '/p/dashboard-user.html', page: 'dashboard-user', roles: ['customer', 'admin'], scripts: [],
          children: [
            { id: 'Dashboard', label: 'Dashboard' },
            { id: 'Orders', label: 'Orders' },
            { id: 'Rewards', label: 'Rewards' }
          ]
        }
      ]
    }
  ];

  /* == Default Menu (parity dengan backend MenuBuilder.gs) ==========
     buildAdminMenu() GAS menyusun urutan: MENU ADMIN, MENU CUSTOMER,
     PLUGINS. Fallback frontend meniru persis urutan itu dari
     DEFAULT_ADMIN_MENU + DEFAULT_CUSTOMER_MENU agar perilaku sama saat
     cache kosong / GAS belum set �?" breadcrumb level-3 dashboard-user
     merespon hash tanpa mapping khusus halaman (gaya plugin). */
  function defaultMenuGroups() {
    var admin = JSON.parse(JSON.stringify(DEFAULT_ADMIN_MENU));
    var cust = JSON.parse(JSON.stringify(DEFAULT_CUSTOMER_MENU));
    var out = [];
    var inserted = false;
    for (var i = 0; i < admin.length; i++) {
      if (admin[i].title === 'PLUGINS' && !inserted) {
        for (var j = 0; j < cust.length; j++) { out.push(cust[j]); }
        inserted = true;
      }
      out.push(admin[i]);
    }
    if (!inserted) {
      for (var k = cust.length - 1; k >= 0; k--) { out.unshift(cust[k]); }
    }
    return out;
  }

  /* == Global Store == */
  var STORE = {
    user: (function () { try { return parseUser(localStorage.getItem(USER_KEY)); } catch (e) { return null; } })(),
    token: (function () { try { return localStorage.getItem(AUTH_KEY); } catch (e) { return null; } })(),
    activeRoute: window.location.hash || '#dashboard',
    openSubmenu: null,
    menuGroups: (function () { var c = getCachedPlugins(); return (c && c.length) ? c : defaultMenuGroups(); })(),
    viewMode: (function () { try { return localStorage.getItem('ezy_view_mode') || null; } catch (e) { return null; } })(),
    sessionChecked: false,
    notifications: [],
    unreadCount: 0,
    notificationsLoading: false,

    effectiveRole: function () {
      var u = this.user;
      if (!u) { return 'guest'; }
      var baseRole = u.role || 'customer';
      if (baseRole === 'admin') {
        return this.viewMode || 'admin';
      }
      return baseRole;
    },

    isAdmin: function () {
      return this.effectiveRole() === 'admin';
    },

    isCustomer: function () {
      return this.effectiveRole() === 'customer';
    },

    setViewMode: function (mode) {
      if (!this.user || this.user.role !== 'admin') { return; }
      this.viewMode = mode;
      try { localStorage.setItem('ezy_view_mode', mode); } catch (e) {}
      this.updateBreadcrumb();
      // Navigasi ke dashboard sesuai mode: customer �+' /p/dashboard-user.html,
      // admin �+' /p/dashboard-admin.html (jadikan halaman yang sedang aktif).
      // SPA: gunakan router (pushState) bila tersedia agar tanpa full reload.
      var target = (mode === 'customer') ? '/p/dashboard-user.html' : '/p/dashboard-admin.html';
      if (window.location.pathname !== target) {
        if (typeof window.navigate === 'function') {
          window.navigate(target);
        } else {
          window.location.href = target;
        }
      }
    },

    dashboardUrl: function () {
      var u = this.user;
      return (u && u.role === 'admin') ? '/p/dashboard-admin.html' : '/p/dashboard-user.html';
    },

    visibleMenuGroups: function () {
      var role = this.effectiveRole();
      var baseGroups = (this.menuGroups && this.menuGroups.length)
        ? this.menuGroups
        : (role === 'admin' ? DEFAULT_ADMIN_MENU : DEFAULT_CUSTOMER_MENU);

      var filtered = [];
      for (var i = 0; i < baseGroups.length; i++) {
        var g = baseGroups[i];
        var items = g.items || [];
        var visibleItems = [];

        // Admin tidak perlu melihat grup MENU CUSTOMER di sidebar
        // (admin menjangkau halaman itu via view-mode / setViewMode).
        // Trip dengan role !== 'admin' tetap dipertahankan apa adanya.
        if (role === 'admin' && /^MENU CUSTOMER$/i.test(String(g.title || ''))) { continue; }

        for (var j = 0; j < items.length; j++) {
          var it = items[j];
          // Profil dikelola di dropdown user header, bukan di sidebar
          // (berlaku untuk semua role, termasuk data cache lama).
          if (it.page === 'profile' || it.link === '/p/profile.html') { continue; }

          if (role === 'admin') {
            visibleItems.push(it);
            continue;
          }

          var isPluginMgr = it.page === 'plugin-manager' || it.link === '/p/plugin-manager.html';
          var isAdminDash = it.page === 'dashboard-admin' || it.link === '/p/dashboard-admin.html' || it.link === '/p/dashboard.html';
          var explicitAdminOnly = it.roles && it.roles.indexOf('admin') !== -1 && it.roles.indexOf('customer') === -1;

          // Plugin HANYA untuk admin: item plugin (berada di grup PLUGINS
          // atau bertanda pluginId) hanya tampil untuk customer bila
          // roles-nya menyertakan 'customer' secara eksplisit.
          var isPluginItem = /plugins/i.test(String(g.title || '')) || !!it.pluginId;
          var pluginForCustomer = it.roles && it.roles.indexOf('customer') !== -1;

          if (isPluginMgr || isAdminDash || explicitAdminOnly) { continue; }
          if (isPluginItem && !pluginForCustomer) { continue; }

          visibleItems.push(it);
        }
        if (visibleItems.length > 0) {
          filtered.push({ title: g.title, items: visibleItems });
        }
      }
      return filtered.length > 0 ? filtered : DEFAULT_CUSTOMER_MENU;
    },

    init: function () {
      if (this.__booted) { return; }
      this.__booted = true;
      var self = this;
      window.addEventListener('hashchange', function () {
        self.activeRoute = window.location.hash || '#dashboard';
        self.restoreSubmenuFromRoute();
        self.updateBreadcrumb();
      });
      // Render ulang menu sidebar setiap kali plugin-manager menandai perubahan.
      window.addEventListener('ezy:menu-update', function () {
        self.loadPlugins();
      });
      // Muat plugin saat inisialisasi agar menu dinamis tampil tanpa
      // perlu membuka plugin-manager terlebih dahulu.
      this.loadPlugins();
      // Set judul halaman untuk breadcrumb level 2 (non-plugin).
      var _titles = {
        'dashboard-admin': 'Dashboard Admin',
        'dashboard-user': 'Dashboard User',
        dashboard: 'Dashboard Admin',
        'plugin-manager': 'Plugin Manager',
        profile: 'Profil',
        'ai-assistant': 'AI Assistant',
        notifikasi: 'Notifikasi'
      };
      this.pageTitle = _titles[pageKind()] || document.title.split('|')[0].trim();
      this.updateBreadcrumb();
      // Catat blogId + konfigurasi ke backend GAS (ScriptProperties)
      // otomatis saat template live & endpoint sudah terisi.
      this.reportConfig();
      // Aktifkan auth guard & verifikasi sesi.
      this.guard();
      this.verifySession();
      // Muat notifikasi dari backend (setelah sesi terverifikasi).
      this.loadNotifications();
      // Refresh notifikasi setiap 60 detik (polling ringan).
      var self = this;
      setInterval(function () { self.loadNotifications(); }, 60000);
    },

    // Kirim konfigurasi (endpoint + blogId + pageId) ke backend GAS
    // sekali per blog/endpoint agar blogId tercatat di ScriptProperties
    // segera setelah user mengisi Web App URL di widget HTML100.
    reportConfig: function () {
      var cfg = null;
      try { cfg = getConfig(); } catch (e) {}
      if (!cfg || !cfg.gasApiEndpoint || !cfg.blogId) { return; }
      var flagKey = 'ezy_reported_' + cfg.blogId + '_' + cfg.gasApiEndpoint.split('?')[0];
      try {
        if (localStorage.getItem(flagKey)) { return; }
        localStorage.setItem(flagKey, '1');
      } catch (e) {}
      this.api('get_config', {
        blogId: cfg.blogId,
        pageId: cfg.pageId || ''
      }).catch(function () {});
    },

    // Muat daftar plugin aktif yang tampil di menu dari backend GAS.
    // Strategi: cache-first (stale-while-revalidate) �?" tampilkan data
    // dari localStorage / default core menu secara instan, lalu fetch
    // fresh data di background tanpa skeleton / blocking.
    loadPlugins: function () {
      var self = this;
      // 1. Hydrate dari cache agar sidebar tampil tanpa delay.
      var cached = getCachedPlugins();
      if (cached && cached.length) {
        self.menuGroups = cached;
        try { if (window.EzyFast && window.EzyFast.primePluginRegistry) { window.EzyFast.primePluginRegistry(cached); } } catch (eP) {}
        loadPluginAssetsForPage(cached);
        self.restoreSubmenuFromRoute();
        self.updateBreadcrumb();
      }
      // 2. Fetch fresh menu dari backend (CORE_MENU + active plugins merged).
      this.api('get_admin_menu').then(function (json) {
        var fresh = (json && json.menuGroups) ? json.menuGroups : [];
        if (fresh.length) {
          self.menuGroups = fresh;
          loadPluginAssetsForPage(fresh);
          setCachedPlugins(fresh);
          try { if (window.EzyFast && window.EzyFast.primePluginRegistry) { window.EzyFast.primePluginRegistry(fresh); } } catch (eP) {}
          self.restoreSubmenuFromRoute();
          self.updateBreadcrumb();
        }
      }).catch(function () {});
    },

    // Buka submenu plugin yang route-nya (pathname + #hash) sedang aktif,
    // sehingga item Products/Orders/Customers langsung terlihat & tersorot.
    // PENTING: key openSubmenu WAJIB sama dengan yang dipakai render/toggle
    // (`p.pluginId || p.page`), bukan `p.id` �?" item CORE bertab seperti
    // dashboard-user tidak punya pluginId/id tapi punya page. Sebelumnya
    // mismatch �+' openSubmenu=undefined �+' submenu & chevron menutup sendiri
    // setiap kali child diklik / hash berubah.
    restoreSubmenuFromRoute: function () {
      var self = this;
      var path = window.location.pathname;
      var hash = window.location.hash || '';
      if (!hash) { return; }
      this.menuGroups.forEach(function (group) {
        (group.items || []).forEach(function (p) {
          if (path === self.pluginUrl(p) && p.children && p.children.length > 0) {
            var hit = p.children.some(function (child) {
              return '#' + self.childRouteKey(child) === hash;
            });
            if (hit) { self.openSubmenu = p.pluginId || p.page; }
          }
        });
      });
    },

    // URL halaman plugin di Blogger (/p/{id}.html).
    pluginUrl: function (p) {
      // pageId = path kanonik terdaftar di Plugins_Active (di-sync tiap
      // kunjungan via set_plugin_meta) �?" diutamakan agar sidebar selalu
      // menunjuk path yang benar meski pageSlug/link sudah basi.
      if (p.pageId && String(p.pageId).charAt(0) === '/') return p.pageId;
      // Support both old format (pageSlug) and new format (link from backend)
      if (p.link) return p.link;
      var slug = p.pageSlug || p.page || p.pluginId || p.id || '';
      return '/p/' + slug + '.html';
    },

    // Toggle expand/collapse submenu plugin di sidebar.
    toggleSubmenu: function (pluginId) {
      this.openSubmenu = (this.openSubmenu === pluginId) ? null : pluginId;
    },

    // Auto-expand submenu saat sidebar dibuka ulang & item aktif berada di dalamnya.
    ensureSubmenuOpen: function (pluginId) {
      if (this.openSubmenu == null) { this.openSubmenu = pluginId; }
    },

    // Kunci kanonik sub-view (hash) sebuah child. Sumber tunggal agar
    // href, isChildActive, restoreSubmenuFromRoute, dan updateBreadcrumb
    // selalu membandingkan '#hash' yang SAMA. Toleran terhadap 3 bentuk
    // data child: {id,label}, {label}, maupun string polos.
    childRouteKey: function (child) {
      if (!child) { return ''; }
      if (typeof child === 'string') { return child; }
      return String(child.id || child.label || '');
    },

    // Sinkronkan state sidebar & breadcrumb dengan route aktif.
    // Dipanggil dari ezy:spa:shell, hashchange, DAN setelah konten
    // selesai di-inject �?" menangkal race antara dispatch shell (sync)
    // dengan fetch konten (async) yang bisa membuat child sub-route
    // (/p/pos.html#Sale) tidak tersorot karena state sempat tertimpa.
    syncSidebarFromRoute: function () {
      try {
        this.activeRoute = window.location.hash || '#dashboard';
        this.restoreSubmenuFromRoute();
        this.updateBreadcrumb();
      } catch (e) {}
    },

    // Apakah child submenu aktif (pathname cocok + activeRoute cocok).
    // Menggunakan store.activeRoute (reaktif, di-update pada hashchange)
    // �?" bukan window.location.hash �?" agar Alpine ikut me-render ulang
    // x-bind:class submenu saat pengguna berpindah tab.
    isChildActive: function (p, child) {
      // Cocokan PATH dulu; bila gagal, terima submenu yang jelas terbuka
      // untuk plugin ini (openSubmenu === pluginId) + hash cocok dengan
      // child �?" menutup kasus trailing slash / encoding / pageSlug custom
      // yang bikin window.location.pathname != pluginUrl().
      if (window.location.pathname === this.pluginUrl(p)) {
        return this.activeRoute === '#' + this.childRouteKey(child);
      }
      return this.openSubmenu === (p.pluginId || p.page) &&
             this.activeRoute === '#' + this.childRouteKey(child);
    },

    // == Breadcrumb reactive ==
    // Menyimpan plugin & child yang cocok dengan route saat ini
    // agar breadcrumb (Beranda > Plugin > Child) bisa dirender
    // secara reaktif oleh Alpine tanpa bergantung pada XML statis.
    breadcrumbPlugin: null,
    breadcrumbChild: null,
    pageTitle: '',

    updateBreadcrumb: function () {
      var self = this;
      var path = window.location.pathname;
      var hash = window.location.hash || '';

      self.breadcrumbPlugin = null;
      self.breadcrumbChild = null;

      // Sumber level-2/level-3: menu aktif + mirror defaultMenuGroups()
      // sebagai jaring pengaman. Ketika menuGroups sementara belum memuat
      // item bertab (mis. cache GAS lama sebelum MenuBuilder.gs direvisi),
      // scan mirror tetap menemukan Dashboard customer berikut children-nya
      // sehingga breadcrumb SELALU sinkron dengan #hash �?" tanpa map statis
      // per halaman (sumber tetap satu: parity backend).
      var scanSet = [this.menuGroups];
      try {
        var _mirror = defaultMenuGroups();
        if (_mirror && _mirror.length) { scanSet.push(_mirror); }
      } catch (e) {}

      var s, g, i, c;
      for (s = 0; s < scanSet.length; s++) {
        var groups = scanSet[s] || [];
        for (g = 0; g < groups.length; g++) {
          var items = groups[g].items || [];
          for (i = 0; i < items.length; i++) {
            var p = items[i];
            if (path !== self.pluginUrl(p)) { continue; }
            if (!self.breadcrumbPlugin) { self.breadcrumbPlugin = p; }
            if (hash && p.children && p.children.length > 0 && !self.breadcrumbChild) {
              for (c = 0; c < p.children.length; c++) {
                if ('#' + self.childRouteKey(p.children[c]) === hash) {
                  self.breadcrumbChild = p.children[c];
                  break;
                }
              }
            }
          }
        }
        if (self.breadcrumbPlugin && (self.breadcrumbChild || !hash)) { break; }
      }
    },

    /* == Notifications: fetch POST CORS-safe, mark-read, helpers =====
       [MIGRASI JSONP -> fetch (CORS-safe, pola referensi EzyCore
       sendDataToGoogle)] Fetch ke GAS Web App cross-origin MEMUNGKINKAN
       selama request TIDAK memicu preflight OPTIONS:
         - Content-Type application/json           �+' PREFLIGHT �+' DIBLOKIR �o-
         - Header Authorization Bearer (custom)     �+' PREFLIGHT �+' DIBLOKIR �o-
         - Content-Type text/plain;charset=utf-8 + token di body �+' simple
           request (CORS-safelisted) �+' TANPA preflight �+' GAS balas respons
           yang terbaca �o"
       Kelima method ini (loadNotifications, markNotificationRead,
       markAllNotificationsRead, deleteNotification, deleteAllNotifications)
       memakai this.api() yang sudah ditulis ulang
       mengikuti pola di atas (bukan api() lama yang memakai
       'application/json' + 'Authorization' �?" penyebab net::ERR_FAILED).
       Konsekuensi backend: kelima action notifikasi WAJIB ditangani doPost
       (Code.gs) karena sudah bukan lagi murni GET/JSONP (lihat switch doPost).
       Setiap notifikasi memiliki struktur:
         { id, type, title, message, url, is_read, created_at }
       Kontrak respons get_notifications yang DIDUKUNG (frontend menormalkan
       keduanya, lihat loadNotifications �?" pastikan backend konsisten pakai
       salah satu):
         1) { status: 'success', notifications: [...], unreadCount: N }  (shape handler doGet/doPost)
         2) { success: true, data: { notifications: [...], unreadCount } } (shape standar api())
       Jika endpoint belum tersedia atau user belum login, diam saja. */
    loadNotifications: function () {
      var self = this;
      if (!self.token) { console.warn('[Notifications] No token, skipping fetch'); return; }
      if (self.notificationsLoading) { return; }
      self.notificationsLoading = true;
      // api() TIDAK PERNAH reject bila HTTP/JSON jalan �?" kegagalan transport
      // (offline, GAS cold start, 302-ke-external, dsb.) tetap resolve sebagai
      // { success:false, error } (lihat implementasi api()). Kegagalan
      // cold-start dibiarkan pulih sendiri di poll berikutnya (60 detik).
      // Token dikirim via body (bukan query string) �?" tidak bocor ke URL.
      self.api('get_notifications', {}).then(function (json) {
        if (!json || json.status === 'error' || json.success === false) {
          self.notificationsLoading = false;
          return;
        }
        // Normalisasi: backend boleh balas flat (shape 1) atau dibungkus
        // { success, data } (shape 2) �?" lihat catatan kontrak di atas.
        var payload = (json.data && typeof json.data === 'object') ? json.data : json;
        self.notifications = payload.notifications || [];
        self.unreadCount = (typeof payload.unreadCount === 'number') ? payload.unreadCount : 0;
        self.notificationsLoading = false;
      }).catch(function () {
        self.notificationsLoading = false;
      });
    },

    markNotificationRead: function (notifId) {
      var self = this;
      if (!self.token || !notifId) { return; }
      // api() selalu resolve �?" cek status:'error' eksplisit sebelum optimistic
      // update lokal (fetch tidak otomatis reject pada respons bisnis error).
      self.api('notification.mark_read', { id: notifId }).then(function (json) {
        if (!json || json.status === 'error' || json.success === false) { return; }
        self.notifications = self.notifications.map(function (n) {
          if (n.id === notifId) { n.is_read = true; }
          return n;
        });
        self.unreadCount = Math.max(0, self.notifications.filter(function (n) { return !n.is_read; }).length);
      }).catch(function () {});
    },

    markAllNotificationsRead: function () {
      var self = this;
      if (!self.token) { return; }
      self.api('notification.mark_all_read', {}).then(function (json) {
        if (!json || json.status === 'error' || json.success === false) { return; }
        self.notifications = self.notifications.map(function (n) { n.is_read = true; return n; });
        self.unreadCount = 0;
      }).catch(function () {});
    },

    deleteNotification: function (notifId) {
      var self = this;
      if (!self.token || !notifId) { return Promise.resolve({ status: 'error', error: 'TOKEN_MISSING' }); }
      return self.api('notification.delete', { id: notifId }).then(function (res) {
        // Kegagalan transport (api() resolve { success:false, error }) dan
        // respons bisnis error dibedakan; .catch() di bawah untuk safety.
        if (!res || res.status === 'error' || res.success === false) { return { status: 'error', error: (res && res.error) || 'NETWORK' }; }
        if (res.status === 'success') {
          self.notifications = self.notifications.filter(function (n) { return n.id !== notifId; });
          self.unreadCount = Math.max(0, self.notifications.filter(function (n) { return !n.is_read; }).length);
        }
        return res || {};
      }).catch(function () { return { status: 'error', error: 'NETWORK' }; });
    },

    deleteAllNotifications: function () {
      var self = this;
      if (!self.token) { return Promise.resolve({ status: 'error', error: 'TOKEN_MISSING' }); }
      return self.api('notification.clear_all', {}).then(function (res) {
        if (!res || res.status === 'error' || res.success === false) { return { status: 'error', error: (res && res.error) || 'NETWORK' }; }
        if (res.status === 'success') {
          self.notifications = [];
          self.unreadCount = 0;
        }
        return res || {};
      }).catch(function () { return { status: 'error', error: 'NETWORK' }; });
    },

    timeAgo: function (dateStr) {
      if (!dateStr) { return ''; }
      var now = Date.now();
      var then = new Date(dateStr).getTime();
      if (isNaN(then)) { return ''; }
      var diff = Math.max(0, Math.floor((now - then) / 1000));
      if (diff < 60) { return 'Baru saja'; }
      if (diff < 3600) { return Math.floor(diff / 60) + ' menit yang lalu'; }
      if (diff < 86400) { return Math.floor(diff / 3600) + ' jam yang lalu'; }
      if (diff < 604800) { return Math.floor(diff / 86400) + ' hari yang lalu'; }
      return new Date(dateStr).toLocaleDateString('id-ID', { day: 'numeric', month: 'short', year: 'numeric' });
    },

    notifIcon: function (type) {
      switch (type) {
        case 'success': return 'circle-check';
        case 'error': return 'circle-x';
        case 'warning': return 'triangle-alert';
        case 'info': default: return 'info';
      }
    },

    notifIconClass: function (type) {
      switch (type) {
        case 'success': return 'text-success-500 bg-success-50 dark:text-success-400 dark:bg-success-500/12';
        case 'error': return 'text-error-500 bg-error-50 dark:text-error-400 dark:bg-error-500/12';
        case 'warning': return 'text-warning-500 bg-warning-50 dark:text-warning-400 dark:bg-warning-500/12';
        case 'info': default: return 'text-brand-500 bg-brand-50 dark:text-brand-400 dark:bg-brand-500/12';
      }
    },

    headerInitials: function () {
      var u = this.user;
      var name = u ? (u.name || u.email || '') : '';
      if (!name) return '';
      var parts = name.trim().split(/\s+/);
      if (parts.length >= 2) return (parts[0][0] + parts[parts.length - 1][0]).toUpperCase();
      return name.slice(0, 2).toUpperCase();
    },

    setAuth: function (user, token) {
      this.user = user || null;
      this.token = token || null;
      try {
        if (this.token) {
          localStorage.setItem(AUTH_KEY, this.token);
          localStorage.setItem(USER_KEY, JSON.stringify(this.user || {}));
        } else {
          localStorage.removeItem(AUTH_KEY);
          localStorage.removeItem(USER_KEY);
        }
      } catch (e) {}
    },

    logout: function () {
      var host = this;
      var token = host.token;
      // Invalidate session di backend sebelum bersihkan state lokal
      if (token) {
        host.api('auth.logout', { token: token }).catch(function () {});
      }
      host.setAuth(null, null);
      // SPA: seamless ke halaman signin tanpa reload penuh bila router aktif.
      if (typeof window.navigate === 'function') {
        window.navigate('/p/signin.html');
      } else {
        window.location.href = '/p/signin.html';
      }
    },

    guard: function () {
      var kind = pageKind();
      var pageRole = PAGE_ROLES[kind] || 'protected';

      // Halaman public: tidak perlu cek
      if (pageRole === 'public') { return; }

      var token = this.token;

      // Halaman guest (signin/signup/reset): jika sudah login, redirect ke dashboard sesuai role
      if (pageRole === 'guest') {
        if (token) {
          var self = this;
          this.api('auth.session.verify', { token: token }).then(function (res) {
            if (res && res.status === 'success' && res.valid) {
              var u = res.user || self.user;
              var target = (u && u.role === 'admin') ? '/p/dashboard-admin.html' : '/p/dashboard-user.html';
              window.location.replace(target);
            } else {
              // Network error (res.success === false tanpa status) = no-op,
              // jangan bersihkan sesi gara-gara koneksi transien.
              if (res && res.success === false && !res.status) { return; }
              self.setAuth(null, null);
            }
          }).catch(function () {});
        }
        return;
      }

      // Halaman protected / admin: jika tidak ada token, redirect ke signin
      if (!token) {
        window.location.replace('/p/signin.html');
        return;
      }

      // Halaman khusus admin: tolak jika bukan role admin
      if (pageRole === 'admin') {
        var currentUser = this.user;
        var uRole = currentUser ? (currentUser.role || 'customer') : 'customer';
        if (uRole !== 'admin') {
          toast('Akses Ditolak: Halaman ini khusus Administrator.', 'error');
          window.location.replace('/p/dashboard-user.html');
          return;
        }
      }
    },

    verifySession: function () {
      var host = this;
      if (!host.token) { return; }
      host.api('auth.session.verify', { token: host.token }).then(function (json) {
        if (json && json.status === 'success' && json.valid) {
          if (json.user) { host.setAuth(json.user, host.token); }
          var kind = pageKind();
          if (PAGE_ROLES[kind] === 'admin' && json.user && json.user.role !== 'admin') {
            toast('Akses Ditolak: Halaman ini khusus Administrator.', 'error');
            window.location.replace('/p/dashboard-user.html');
          }
        } else {
          // Network error (json.success === false tanpa status) = no-op,
          // jangan logout hanya karena koneksi transien.
          if (json && json.success === false && !json.status) { return; }
          host.logout();
        }
      }).catch(function () {});
    },

    api: function (action, options) {
      var endpoint = getConfig().gasApiEndpoint;
      if (!endpoint) {
        toast('Endpoint GAS belum dikonfigurasi di menu Tata Letak.', 'error');
        return Promise.resolve({ success: false, error: 'GAS_ENDPOINT_MISSING' });
      }
      // CORS-SAFE POST (pola referensi EzyCore sendDataToGoogle): GAS Web
      // App membungkam preflight (OPTIONS) karena ContentService tidak bisa
      // mengirim header ACAO �?" jadi request HARUS "simple" agar lolos:
      //   1) Content-Type text/plain;charset=utf-8 (CORS-safelisted), BUKAN
      //      application/json yang memicu preflight.
      //   2) TANPA header custom (Authorization Bearer) �?" token dikirim
      //      dalam body, tidak pernah tampil di URL.
      // GAS membalas simple request dengan Access-Control-Allow-Origin: *,
      // sehingga fetch tetap dapat membaca respons (res.json()).
      var payload = Object.assign({}, options || {});
      payload.action = action;
      if (this.token && !('token' in payload)) { payload.token = this.token; }
      var cfg = null;
      try { cfg = getConfig(); } catch (e) {}
      if (cfg && cfg.blogId && !('blogId' in payload)) { payload.blogId = cfg.blogId; }
      return fetch(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'text/plain;charset=utf-8' },
        body: JSON.stringify(payload)
      }).then(function (res) { return res.json(); }).catch(function (err) {
        return { success: false, error: String(err) };
      });
    }
  };

  document.addEventListener('alpine:init', function () {
    Alpine.store('admin', STORE);

    // Alpine TIDAK memanggil method `init` pada store (lifecycle itu
    // khusus komponen). Tanpa panggilan eksplisit, STORE.init (listener
    // hashchange, loadPlugins untuk menu plugin dinamis, guard, dsb.)
    // mati selamanya �?" itulah kenapa submenu plugin dinamis (POS) tidak
    // pernah tersorot: menu POS tidak pernah dimuat dari backend dan
    // hash sub-route tidak pernah menyinkronkan activeRoute. Jalankan
    // sekali saat boot, hanya di halaman admin/protected (bukan
    // standalone public seperti signin untuk menghindari noise request).
    try {
      var initKind = pageKind();
      if (PAGE_ROLES[initKind] !== 'public' &&
          PAGE_ROLES[initKind] !== 'guest' &&
          typeof STORE.init === 'function') {
        setTimeout(function () { try { STORE.init(); } catch (e) {} }, 0);
      }
    } catch (e) {}

    /* == Guide Tour Store: onboarding overlay spotlight =================
       Berjalan di halaman standalone (home, signin, dst.) tanpa library
       eksternal. Spotlight menggunakan box-shadow raksasa pada elemen
       fixed-position; tooltip diposisikan dinamis berdasarkan bounding
       rect target. State disimpan di localStorage agar tour hanya
       berjalan sekali per browser. */
    Alpine.store('tour', {
      active: false,
      currentStep: 0,
      completed: false,
      spotlightStyle: '',
      tooltipStyle: '',
      steps: [
        {
          target: '.ezy-nav a[href="/p/signin.html"]',
          text: 'Klik di sini untuk masuk ke panel admin dengan akun Anda.',
        },
        {
          target: '.ezy-nav a[href="/p/signup.html"]',
          text: 'Belum punya akun? Daftar gratis dalam hitungan detik.',
        },
        {
          target: '.ezy-btn-row a[href="/p/signin.html"]',
          text: 'Mulai kelola website Anda dari dasbor yang modern dan cepat.',
        }
      ],

      init: function () {
        try { this.completed = localStorage.getItem('ezy_tour_done') === '1'; } catch (e) {}
      },

      start: function () {
        this.active = true;
        this.currentStep = 0;
        var self = this;
        setTimeout(function () { self.highlight(); }, 200);
      },

      next: function () {
        if (this.currentStep < this.steps.length - 1) {
          this.currentStep++;
          var self = this;
          setTimeout(function () { self.highlight(); }, 200);
        } else {
          this.finish();
        }
      },

      prev: function () {
        if (this.currentStep > 0) {
          this.currentStep--;
          var self = this;
          setTimeout(function () { self.highlight(); }, 200);
        }
      },

      finish: function () {
        this.active = false;
        this.completed = true;
        try { localStorage.setItem('ezy_tour_done', '1'); } catch (e) {}
      },

      highlight: function () {
        var step = this.steps[this.currentStep];
        var el = document.querySelector(step.target);
        if (!el) { this.next(); return; }

        var self = this;
        el.scrollIntoView({ behavior: 'smooth', block: 'center' });

        setTimeout(function () {
          var rect = el.getBoundingClientRect();
          var pad = 10;
          self.spotlightStyle =
            'top:' + (rect.top - pad) + 'px;' +
            'left:' + (rect.left - pad) + 'px;' +
            'width:' + (rect.width + pad * 2) + 'px;' +
            'height:' + (rect.height + pad * 2) + 'px;';

          /* Tooltip: deteksi batas viewport agar tidak terpotong */
          var vw = window.innerWidth;
          var vh = window.innerHeight;
          var tipW = 300;
          var tipH = 160;
          var gap = 16;
          var margin = 16;

          /* Vertikal: coba di bawah, flip ke atas jika overflow */
          var tooltipTop = rect.bottom + pad + gap;
          if (tooltipTop + tipH > vh - margin) {
            tooltipTop = rect.top - pad - tipH - gap;
          }
          if (tooltipTop < margin) { tooltipTop = margin; }

          /* Horizontal: center pada target, clamp ke viewport */
          var tooltipLeft = rect.left + rect.width / 2;
          if (tooltipLeft - tipW / 2 < margin) {
            tooltipLeft = tipW / 2 + margin;
          }
          if (tooltipLeft + tipW / 2 > vw - margin) {
            tooltipLeft = vw - tipW / 2 - margin;
          }

          self.tooltipStyle =
            'top:' + tooltipTop + 'px;' +
            'left:' + tooltipLeft + 'px;' +
            'transform:translateX(-50%);';
        }, 350);
      }
    });

    Alpine.data('shell', function () {
      var kind = pageKind();
      var standalone = kind === 'home' || kind === 'signin' || kind === 'signup' || kind === 'reset-password';
      var fileMap = {
        home: '/p/home.html',
        signin: '/p/signin.html',
        signup: '/p/signup.html',
        'reset-password': '/p/reset-password.html'
      };
      return {
        pathname: window.location.pathname,
        page: kind,
        isHome: kind === 'home',
        isStandalone: standalone,
        contentFile: fileMap[kind] || '',
        darkMode: (function () { try { return localStorage.getItem('ezy_dark') === 'true'; } catch (e) { return false; } })(),
        sidebarToggle: false,
        scrollTop: false,
        loaded: true,
        notice: null,
        standaloneContent: '',

        init: function () {
          var self = this;
          try { document.documentElement.classList.toggle('dark', self.darkMode); } catch (e) {}
          this.$watch('darkMode', function (v) {
            try {
