          if (_pb) {
            function paintProgress(e) {
              var sc = e && e.target;
              if (!sc || sc === document || sc === document.documentElement || sc.scrollTop === undefined) {
                sc = document.scrollingElement || document.documentElement;
              }
              var max = Math.max(0, (sc.scrollHeight || 0) - (sc.clientHeight || 0));
              var cur = (sc === document.scrollingElement || sc === document.documentElement)
                ? (window.scrollY || sc.scrollTop || 0)
                : (sc.scrollTop || 0);
              _pb.style.width = (max > 0 ? Math.min(100, (cur / max) * 100) : 0) + '%';
            }
            document.addEventListener('scroll', paintProgress, true);
            window.addEventListener('resize', paintProgress);
            paintProgress(null);
          }
          window.addEventListener('ezy:toast', function (e) {
            self.notice = { message: e.detail.message, type: e.detail.type || 'success', key: Date.now() };
          });
          this.initStandalone();
          this.initSpa();
        },

        initStandalone: function (targetOverride) {
          if (!this.isStandalone && !targetOverride) { return; }
          var host = this;

          // Redirect /p/home.html �+' / (canonical URL, hindari duplicate content)
          if (host.isHome && window.location.pathname !== '/' && !targetOverride) {
            window.location.replace('/');
            return;
          }
          var metaEl = document.getElementById('ezy-blog-meta');
          var title = metaEl ? (document.getElementById('ezy-blog-title') ? document.getElementById('ezy-blog-title').textContent : '') : '';
          var descEl = document.getElementById('ezy-blog-desc-widget') || document.getElementById('ezy-blog-desc');
          var desc = descEl ? (descEl.textContent || '').trim() : '';
          var favicon = document.getElementById('ezy-blog-favicon') ? (document.getElementById('ezy-blog-favicon').textContent || '').trim() : '';
          // Script inline hasil injeksi (innerHTML) tidak dieksekusi browser �?"
          // ezySignin/ezySignup/ezyResetPass baru ada setelah script di-kloning
          // & dipasang ulang. PENTING: re-eksekusi harus terjadi SINKRON di
          // task yang sama dengan penulisan innerHTML �?" sebelum MutationObserver
          // Alpine mengevaluasi x-data="ezySignin()". Ini alasan konten standalone
          // TIDAK boleh memakai x-html (observer Alpine meng-init x-data SEBELUM
          // script jalan �+' 'ezySignin is not defined'). Urutan di bawah identik
          // dengan router admin (injectContent �+' reExecuteDynamicContent �+' initTree).
          function reexecuteStandaloneScripts(container) {
            if (!container) { return; }
            var nodes = container.querySelectorAll('script');
            for (var i = nodes.length - 1; i >= 0; i--) {
              var oldNode = nodes[i];
