            containerEl.innerHTML = out;
            // Sinkron di task ini: global (ezySignin dst.) sudah terdefinisi
            // sebelum Alpine mana pun meng-init x-data konten yang baru.
            try { reexecuteStandaloneScripts(containerEl); } catch (e) {}
