            if (host._standaloneApplySeq !== applySeq) { return; }
            var out = html.replace(/\{\{blogTitle\}\}/g, title).replace(/\{\{blogDesc\}\}/g, desc).replace(/\{\{blogFavicon\}\}/g, favicon);
            var containerEl = overrideEl || document.getElementById('ezy-landing-standalone');
            if (!containerEl) { return; }
            applyStandaloneContent(out, containerEl);
          }
