            applyAndCompile(currentPostBody.innerHTML, overrideEl);
          } else {
            fetch(host.contentFile).then(function (r) { return r.text(); }).then(function (html) {
              if (host._standaloneApplySeq !== applySeq) { return; }
              var doc = new DOMParser().parseFromString(html, 'text/html');
              var el = doc.querySelector('#main .post-body') || doc.querySelector('.post-body');
              if (el) {
                window.__ezyStandaloneCache[targetPath] = el.innerHTML;
                applyAndCompile(el.innerHTML, overrideEl);
              }
            }).catch(function () {});
          }
        },

        displayName: function () {
          var u = this.$store.admin.user;
          if (u) { return u.name || u.username || u.email || 'Admin'; }
          return 'Masuk';
        },

        logout: function () { this.$store.admin.logout(); },

        /* == SPA bridge methods ===================================
           initStandalone menyediakan kontrol konten standalone.
           initSpa menghubungkan router (window.__EzySpa) dengan
           state shell ini & store admin via event. */
        initSpa: function () {
          var self = this;
          window.addEventListener('ezy:spa:standalone', function (e) {
            var d = e.detail || {};
            var page = d.page || 'home';
            var fileMap = {
              home: '/p/home.html',
              signin: '/p/signin.html',
              signup: '/p/signup.html',
              'reset-password': '/p/reset-password.html'
            };
            self.page = page;
            self.isHome = page === 'home';
            self.isStandalone = true;
            self.contentFile = fileMap[page] || '';
            self.pathname = window.location.pathname;
            setTimeout(function () {
              self.initStandalone();
            }, 0);
          });
          window.addEventListener('ezy:spa:shell', function (e) {
            var d = e.detail || {};
