                  typeof _stBoot.init === 'function') { _stBoot.init(); }
            } catch (e) {}
            // Sinkronkan breadcrumb, submenu, & judul level-2 dengan route baru.
            try {
              var st = window.Alpine && window.Alpine.store('admin');
              if (st) {
                st.activeRoute = window.location.hash || '#dashboard';
                // pageTitle (fallback breadcrumb level-2 non-plugin) hanya
                // di-set sekali saat boot di MPA; SPA harus ikut berpindah
                // halaman, jika tidak breadcrumb menampilkan judul lama.
                var _spaTitles = {
                  'dashboard-admin': 'Dashboard Admin',
                  'dashboard-user': 'Dashboard User',
                  dashboard: 'Dashboard Admin',
                  'plugin-manager': 'Plugin Manager',
                  profile: 'Profil',
                  'ai-assistant': 'AI Assistant',
                  notifikasi: 'Notifikasi'
                };
                st.pageTitle = _spaTitles[d.page] || document.title.split('|')[0].trim();
                if (typeof st.restoreSubmenuFromRoute === 'function') { st.restoreSubmenuFromRoute(); }
                if (typeof st.updateBreadcrumb === 'function') { st.updateBreadcrumb(); }
