          });
        }
      };
    });
  });

  /* == Storage Integrity Watchdog =============================
     Mendeteksi `localStorage.clear()` (via DevTools / programmatic)
     pada tab aktif �?" yang TIDAK memicu event 'storage' (event itu
     hanya fires di tab LAIN). Pada page load, snapshot token &
     EzyfastConfig. Setiap kali user berpindah hash (navigasi child
     menu plugin), re-check: bila token DAN config SEMULA ADA tapi
     SEKARANG HILANG �+' localStorage sudah di-clear �+' paksa full
     reload agar preloader, self-recovery bootstrapper, dan Alpine
     re-init secara bersih.

     Catatan: case clear-berlangsung-SELEBENTAR (tanpa hashchange,
     mis. user di /p/pos.html#Sale lalu clear via DevTools) juga
     terdeteksi lewat polling interval 1,2 dtk & visibilitychange
     (tab kembali terlihat setelah external wipe), jadi reload tetap
     terjadi tanpa perlu user berpindah hash dulu.

     Logout normal (hanya menghapus token, config tetap ada) TIDAK
     akan memicu reload �?" hanya localStorage.clear() yang menghapus
     SEMUA key (termasuk EzyfastConfig) yang terdeteksi. */
  (function () {
    try {
      var AUTH_KEY_WD = 'ezy_auth_token';
      var CFG_KEY_WD  = 'EzyfastConfig';
      var snapToken, snapConfig;
      try { snapToken = localStorage.getItem(AUTH_KEY_WD); } catch (e) {}
      try { snapConfig = localStorage.getItem(CFG_KEY_WD); }  catch (e) {}
      /* Tidak ada yang di-snapshot �+' bukan halaman terproteksi, skip */
      if (!snapToken && !snapConfig) { return; }
      var reloading = false;
      function _ezyCheckStorage() {
        if (reloading) { return; }
        var curToken = null, curConfig = null, readOk = true;
        /* Storage sempat tidak terbaca (exception) BUKAN berarti di-clear �?"
           jangan reload hanya karena error baca transient. */
        try { curToken = localStorage.getItem(AUTH_KEY_WD); }  catch (e) { readOk = false; }
        try { curConfig = localStorage.getItem(CFG_KEY_WD); }  catch (e) { readOk = false; }
        if (!readOk) { return; }
        /* Keduanya hilang = localStorage.clear() dilakukan. Logout biasa
           hanya menghapus token (config tetap tersimpan). */
        if (snapToken && !curToken && snapConfig && !curConfig) {
          reloading = true;
          setTimeout(function () { try { window.location.reload(); } catch (e) {} }, 250);
