    if (a.target === '_blank') { return; }
    if (hrefAttr === '#' || hrefAttr === '#/' || hrefAttr.startsWith('#')) { return; }
    if (event.metaKey || event.ctrlKey || event.shiftKey || event.altKey) { return; }
    if (event.button !== 0) { return; }

    var href = a instanceof HTMLAnchorElement ? a.href : hrefAttr;
    if (/^(mailto:|tel:|javascript:|data:)/i.test(href)) { return; }
    var origin = window.location.origin;
    if (href.indexOf('http') === 0 && href.indexOf(origin) !== 0) { return; }
    var path = href.indexOf(origin) === 0 ? href.slice(origin.length) : href;
    if (path.charAt(0) !== '/') { return; }

    // Hanya hash berubah di path yang sama �+' biarkan handler hashchange store.
    var pathOnly = path.split('#')[0].replace(/\/$/, '') || '/';
    var currentPath = window.location.pathname.replace(/\/$/, '') || '/';
    if (pathOnly === currentPath) { return; }

    event.preventDefault();
    window.navigate(path);
  }, true);

  // == Sinkron state URL (back/forward & script-inserted navigation) ==
  window.addEventListener('popstate', function () { render(); });
  window.addEventListener('hashchange', handleHashChange);

  // == Boot: direct-hit halaman admin �+' panggil render agar alur SPA
  //    konsisten (native #main .post-body diumpankan via cache). ==
  function boot() {
    var kind = pageKindFor(window.location.pathname);
    // Standalone (home/signin/signup/reset): shell native initStandalone
    // menangani render �?" router tidak boleh ikut campur (hindari
    // double-render). Homepage '/' sudah dirender langsung oleh Blog1.
    // Search (/{search}) juga dibiarkan native SSR.
    if (isStandaloneKind(kind) || kind === 'search') { return; }
    dispatch('ezy:spa:shell', { page: kind, path: window.location.pathname });
    setTitleFromPath(window.location.pathname);

    // Direct-hit tanpa fetch: MAUKAN node .post-body native ke
    // #ezy-admin-content (bukan copy innerHTML) agar event listener
    // & Alpine state yang sudah ter-eksekusi oleh SSR tetap hidup.
    // Cache innerHTML-nya dulu untuk navigasi berikutnya.
    var native = document.querySelector('#main .post-body');
    var target = document.getElementById('ezy-admin-content');
    if (native && target && native.innerHTML.trim() !== '') {
      var norm = window.location.pathname.replace(/\/$/, '') || '/';
      CACHE[norm] = native.innerHTML;
      target.appendChild(native);
      return;
    }
    // Halaman blog biasa / 404 tanpa native content: biarkan tampilan
    // Blogger native (overlay 404 sudah dirender server-side).
    if (kind === 'page') { return; }
    render();
  }

  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', boot);
  } else {
    boot();
  }
})();
//

head.b:skin:
/*
<Group description="EzyFast Admin - Warna" selector="body">
  <Variable name="brand.primary" description="Warna Brand Utama" type="color" default="#465fff" value="#465fff"/>
  <Variable name="body.background.color" description="Warna Latar Belakang" type="color" default="#f9fafb" value="#f9fafb"/>
</Group>
*/
:root { --brand-primary: $(brand.primary); }

/* Tipografi isi postingan (post-body) */
.post-body { font-size: 16px; line-height: 1.85; word-break: break-word; color: #344054; }
.post-body p { margin: .9em 0; }
.post-body img { height: auto; max-width: 100%; border-radius: 12px; margin: 1.25rem 0; }
.post-body a { color: var(--brand-primary); text-decoration: underline; text-underline-offset: 3px; }
.post-body h1, .post-body h2, .post-body h3, .post-body h4, .post-body h5 {
  font-weight: 600; line-height: 1.3; margin: 1.5em 0 .6em; color: #101828;
}
.post-body h1 { font-size: 1.75em; }
.post-body h2 { font-size: 1.5em; }
.post-body h3 { font-size: 1.25em; }
.post-body h4 { font-size: 1.1em; }
.post-body ul, .post-body ol { margin: .9em 0; padding-left: 1.4em; }
.post-body ul { list-style: disc; }
.post-body ol { list-style: decimal; }
.post-body li { margin: .35em 0; }
.post-body blockquote {
  margin: 1.25em 0; padding: .75rem 1.1rem;
  border-left: 4px solid #c2d6ff; background: #f9fafb;
  border-radius: 0 12px 12px 0; color: #344054;
}
.post-body pre {
  background: #101828; color: #e4e7ec; padding: 1rem 1.25rem;
  border-radius: 12px; overflow: auto; font-size: .875rem; margin: 1.25em 0;
}
.post-body pre code { background: transparent; padding: 0; color: inherit; }
.post-body code { background: #f2f4f7; padding: .15em .4em; border-radius: 6px; font-size: .875em; }
.post-body table { width: 100%; border-collapse: collapse; margin: 1.25em 0; display: block; overflow-x: auto; }
.post-body th, .post-body td { border: 1px solid #e4e7ec; padding: .6rem .9rem; text-align: left; vertical-align: top; }
.post-body th { background: #f9fafb; font-weight: 600; }
.post-body hr { margin: 2em 0; border: 0; border-top: 1px solid #e4e7ec; }
.post-body iframe { max-width: 100%; }

/* Versi gelap */
.dark .post-body { color: #d0d5dd; }
.dark .post-body h1, .dark .post-body h2, .dark .post-body h3,
.dark .post-body h4, .dark .post-body h5 { color: rgba(255,255,255,.9); }
.dark .post-body blockquote { background: rgba(255,255,255,.03); border-left-color: #252dae; color: #98a2b3; }
.dark .post-body code { background: rgba(255,255,255,.08); }
.dark .post-body th, .dark .post-body td { border-color: #1d2939; }
.dark .post-body th { background: rgba(255,255,255,.03); }
.dark .post-body hr { border-top-color: #1d2939; }

/* Komentar Blogger (penyesuaian ringan) */
#comments { margin-top: 1rem; }
#comments a { color: var(--brand-primary); }
#comments .comment-actions a { text-decoration: none; }

b:if.b:template-skin:
/* ============================================
   Admin Panel - Layout Mode
   ============================================ */
body#layout{
  position:relative;
  max-width:1200px;
  min-width:950px;
  margin:0 auto;
  padding:14px;
  box-sizing:border-box;
  font-family:Arial,sans-serif;
  background:#eef0f4;
}
/* ============================================================
   Susunan panel kiri (mode Layout), dari atas ke bawah:
     1. Section Header  (#sidebar-brand / widget Header1)
     2. Badge "EzyFast Admin"
     3. Label "Admin Panel"
     4. Panduan "CARA PENGGUNAAN" (+ 3 langkah)
     5. Copyright
   ============================================================ */
/* .adminbar = panel kiri gradient penuh */
body#layout .adminbar{
  display:block !important;
  width:280px;
  height:100%;
  position:absolute;
  top:0;
  bottom:0;
  left:0;
  z-index:998;
  box-sizing:border-box;
  padding:150px 14px 60px;
  background-color:#465fff;
  background:-moz-linear-gradient(45deg,#465fff 0%,#465fff 25%,#3641f5 100%);
  background:-webkit-linear-gradient(45deg,#465fff 0%,#465fff 25%,#3641f5 100%);
  background:linear-gradient(45deg,#465fff 0%,#465fff 25%,#3641f5 100%);
}
/* 4. Panduan: semua baris teks menyatu dalam flow normal */
body#layout .adminbar .guide,
body#layout .adminbar .theme-opt{
  display:block;
  margin:0;
  color:rgba(255,255,255,.85);
  font-family:Arial,sans-serif;
  font-size:11px;
  line-height:1.6;
  text-align:left;
  position:static !important;
  background:none !important;
  border:none !important;
  border-radius:0 !important;
  padding:0 !important;
  width:auto !important;
  height:auto !important;
}
/* 2. Badge "EzyFast Admin" */
body#layout .adminbar:before{
  content:"EzyFast Admin";
  position:relative;
  display:block;
  width:auto;
  margin:0 0 10px;
  padding:12px 0;
  text-align:center;
  color:#fff;
  font-family:Arial,sans-serif;
  font-size:20px;
  font-weight:bold;
  letter-spacing:1px;
  box-sizing:border-box;
  background:rgba(255,255,255,.12);
  border:1px solid rgba(255,255,255,.35);
  border-radius:10px;
}
/* 3. Label "Admin Panel" (theme-opt) */
body#layout .adminbar .theme-opt:before{
  content:"Admin Panel";
  display:block;
  position:static;
  margin:0 0 8px;
  color:rgba(255,255,255,.8);
  font-family:Arial,sans-serif;
  font-size:11px;
  font-weight:400;
  letter-spacing:2px;
  text-transform:uppercase;
  text-align:left;
}
/* Panduan: judul + langkah */
body#layout .adminbar .guide-title{
  margin-top:8px;
}
body#layout .adminbar .guide-title:before{
  content:"CARA PENGGUNAAN:";
  font-weight:bold;
  letter-spacing:1px;
  text-transform:uppercase;
}
body#layout .adminbar .guide-1:before{
  content:"1. Widget 'Postingan Blog' (Blog1) = daftar posting.";
}
body#layout .adminbar .guide-2:before{
  content:"2. Widget 'EzyFast Endpoint GAS' (HTML100) = konfigurasi.";
}
body#layout .adminbar .guide-3:before{
  content:"3. Edit widget: klik ikon pensil untuk ubah konten.";
}
body#layout .adminbar .guide + .guide{
  margin-top:4px;
}
/* 5. Copyright: ditempel di bawah */
body#layout .adminbar:after{
  content:"(C) Copyright 2026, EzyFast Admin.";
  position:absolute;
  bottom:18px;
  left:0;
  width:100%;
  color:rgba(255,255,255,.7);
  font-family:Arial,sans-serif;
  font-weight:bold;
  font-size:11px;
  text-align:center;
}
/* 1. Section Header (#sidebar-brand) diletakkan di bagian atas panel,
   DI ATAS badge. z-index tinggi agar tampil di atas panel gradient. */
body#layout .sidebar{
  display:block !important;
  width:280px;
  height:auto;
  position:absolute;
  top:0;
  left:0;
  z-index:1000;
  box-sizing:border-box;
  padding:0;
  background:transparent;
  border:none;
  box-shadow:none;
  margin:0;
}
body#layout .sidebar nav,
body#layout .sidebar .promo-box,
body#layout .sidebar > div:not(.sidebar-header){display:none !important;}
/* Sembunyikan SEMUA menu mentah (non-widget) di sidebar pada Layout agar
   titik hitam dari <ul>/<li> menu tak tembus ke tata letak. */
body#layout .sidebar ul,
body#layout .sidebar li,
body#layout .sidebar .menu-group-title,
body#layout .sidebar .menu-item,
body#layout .sidebar .menu-group{display:none !important;}
body#layout .sidebar .sidebar-header{
  display:block;
  margin:0;
  padding:16px 14px 12px;
  background:rgba(255,255,255,.08);
  border-bottom:1px solid rgba(255,255,255,.25);
}
/* ===== #sidebar-brand (widget Header1) di dalam panel kiri gradient =====
   Tampil sebagai barang brand: tanpa card default section, teks putih. */
body#layout #sidebar-brand{
  background:transparent !important;
  border:none !important;
  box-shadow:none !important;
  margin:0 !important;
  padding:0 14px !important;
}
body#layout #sidebar-brand h4{
  display:none !important;
}
body#layout #sidebar-brand div.widget,
body#layout #sidebar-brand .widget{
  padding:0 !important;
  background:transparent !important;
  border:none !important;
  box-shadow:none !important;
}
body#layout #sidebar-brand .widget-content{
  padding:0 !important;
}
body#layout #sidebar-brand a{
  display:flex;
  align-items:center;
  gap:10px;
  color:#fff !important;
  text-decoration:none;
}
body#layout #sidebar-brand .logo-icon{display:none !important;}
body#layout #sidebar-brand img{
  display:block;
  flex:none;
  width:36px;
  height:36px;
  border-radius:8px;
  object-fit:contain;
  background:rgba(255,255,255,.9);
  padding:2px;
}
/* ===== Section cards (gaya konsisten untuk area kanan) ===== */
body#layout .section{
  background:#fff !important;
  margin:0 0 14px !important;
  padding:0 !important;
  border:1px solid #e3e5ea;
  border-radius:10px;
  box-sizing:border-box;
  box-shadow:0 1px 2px rgba(15,23,42,.04);
}
body#layout div.section h4{
  margin:0;
  padding:9px 14px;
  background:#fafbfc;
  color:#465fff;
  font-size:11px;
  font-weight:700;
  text-transform:uppercase;
  letter-spacing:.6px;
  border-bottom:1px solid #eceef1;
  border-radius:9px 9px 0 0;
}
body#layout div.section h4:before{
  content:'';
  display:inline-block;
  width:6px;
  height:6px;
  margin-right:8px;
  border-radius:50%;
  background:#465fff;
  vertical-align:1px;
}
body#layout div.widget .widget-content{
  padding:10px;
}
body#layout .add_widget{
  border:1px dashed #465fff;
  background:#f2f7ff;
  border-radius:6px;
  text-align:center;
}
body#layout .add_widget a{font-weight:700}
/* Sembunyikan tombol "Tambah Gadget" khusus di section konfigurasi
   (showaddelement='yes' agar widget dirender, tapi tanpa tombol tambah). */
body#layout #admin-config-section .add_widget{
  display:none !important;
}
/* Main area: Blog1 minimal. Konten ditolak ke kanan selebar panel kiri (300px). */
body#layout main{
  margin-left:300px;
}
body#layout main > div{padding:0 !important;max-width:none !important}
body#layout #main-layout{overflow:hidden}
body#layout #main{
  min-height:220px;
  box-sizing:border-box;
}
/* Config section: kini di dalam <main> (di atas #main), jadi ikut
   margin-left dari <main> (300px) dan tidak perlu margin sendiri. */
body#layout #admin-config-section{
  clear:both;
  margin-left:0;
  margin-top:14px;
  background:#f6f7f9;
  padding:14px;
  border-radius:10px;
  box-sizing:border-box;
  overflow:hidden;
}

body.script:
//
document.addEventListener('DOMContentLoaded', function () {
  var year = document.getElementById('year');
  if (year) { year.textContent = new Date().getFullYear(); }
  var landingYear = document.getElementById('landing-year');
  if (landingYear) { landingYear.textContent = new Date().getFullYear(); }

  var searchInput = document.getElementById('search-input');
  function focusSearch() {
    if (searchInput) { searchInput.focus(); }
  }
  document.addEventListener('keydown', function (event) {
    if ((event.metaKey || event.ctrlKey) && event.key === 'k') {
      event.preventDefault();
      focusSearch();
    }
    if (event.key === '/' && document.activeElement !== searchInput) {
      event.preventDefault();
      focusSearch();
    }
  });
  var searchButton = document.getElementById('search-button');
  if (searchButton && searchInput) {
    searchButton.addEventListener('click', focusSearch);
  }
});
//
